class Transactions extends StatefulWidget{final VoidCallback changed;const Transactions({super.key,required this.changed});@override State<Transactions> createState()=>_TransactionsState();}
class _TransactionsState extends State<Transactions>{String filter='Semua',q='';Future<void> form([Map<String,dynamic>? e])async{final ok=await Navigator.push(context,MaterialPageRoute(builder:(_)=>TxForm(row:e)));if(ok==true){setState((){});widget.changed();}}@override Widget build(BuildContext c)=>Column(children:[heading('Transaksi','Catatan kas dalam satu tempat',action:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(tooltip:'Kelola kategori',onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const Categories())),icon:const Icon(Icons.category_outlined,color:navy)),IconButton(tooltip:'Tambah transaksi',onPressed:()=>form(),icon:const Icon(Icons.add_circle,color:blue,size:30))])),Padding(padding:const EdgeInsets.symmetric(horizontal:18),child:TextField(onChanged:(v)=>setState(()=>q=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari transaksi'))),Padding(padding:const EdgeInsets.all(12),child:Wrap(spacing:6,children:['Semua','Pemasukan','Pengeluaran'].map((v)=>ChoiceChip(label:Text(v),selected:filter==v,onSelected:(_)=>setState(()=>filter=v))).toList())),Expanded(child:FutureBuilder(future:DB.i.tx(type:filter=='Semua'?null:filter),builder:(c,s){final rows=(s.data??[]).where((e)=>'${e['nama_kategori']} ${e['keterangan']}'.toLowerCase().contains(q.toLowerCase())).toList();return rows.isEmpty?const Center(child:Text('Belum ada transaksi')):ListView(padding:const EdgeInsets.symmetric(horizontal:18),children:[card(Column(children:rows.map((e)=>InkWell(onTap:()=>form(e),child:TxTile(e))).toList()))]);}))]);}

class TxForm extends StatefulWidget{final Map<String,dynamic>? row;const TxForm({super.key,this.row});@override State<TxForm> createState()=>_TxFormState();}
class _TxFormState extends State<TxForm>{final amount=TextEditingController(),note=TextEditingController();String type='Pemasukan',date=DateFormat('yyyy-MM-dd').format(DateTime.now());int? cat,student;@override void initState(){super.initState();final r=widget.row;if(r!=null){type=r['jenis'];amount.text='${r['jumlah']}';note.text=r['keterangan']??'';date=r['tanggal'];cat=r['id_kategori'];student=r['id_siswa'];}}@override void dispose(){amount.dispose();note.dispose();super.dispose();}
 @override Widget build(BuildContext c)=>FutureBuilder(future:Future.wait([DB.i.all('kategori'),DB.i.all('siswa')]),builder:(c,s){if(!s.hasData)return const Scaffold(body:Center(child:CircularProgressIndicator()));final cats=(s.data![0] as List).where((e)=>e['jenis']==type).toList(),students=s.data![1] as List;if(cat!=null&&!cats.any((e)=>e['id_kategori']==cat))cat=null;
 return Scaffold(appBar:AppBar(title:Text(widget.row==null?'Tambah transaksi':'Edit transaksi')),body:ListView(padding:const EdgeInsets.all(18),children:[label('Jenis transaksi'),Wrap(spacing:8,children:['Pemasukan','Pengeluaran'].map((v)=>ChoiceChip(label:Text(v),selected:type==v,onSelected:(_)=>setState(()=>type=v))).toList()),label('Jumlah'),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(prefixText:'Rp ',hintText:'50000')),label('Kategori'),DropdownButtonFormField<int>(value:cat,items:cats.map((e)=>DropdownMenuItem<int>(value:e['id_kategori'],child:Text(e['nama_kategori']))).toList(),onChanged:(v)=>setState(()=>cat=v),decoration:const InputDecoration(hintText:'Pilih kategori')),label('Tanggal'),OutlinedButton.icon(onPressed:()async{final d=await showDatePicker(context:c,initialDate:DateTime.tryParse(date)??DateTime.now(),firstDate:DateTime(2020),lastDate:DateTime(2100));if(d!=null)setState(()=>date=DateFormat('yyyy-MM-dd').format(d));},icon:const Icon(Icons.calendar_today),label:Text(date)),label('Keterangan'),TextField(controller:note,decoration:const InputDecoration(hintText:'Masukkan keterangan')),label('Pembayaran siswa (opsional)'),DropdownButtonFormField<int>(value:student,items:[const DropdownMenuItem<int>(value:null,child:Text('Tidak terkait siswa')),...students.map((e)=>DropdownMenuItem<int>(value:e['id_siswa'],child:Text(e['nama_siswa'])))],onChanged:(v)=>setState(()=>student=v)),const SizedBox(height:24),btn('Simpan transaksi',()async{final n=double.tryParse(amount.text.replaceAll('.','').replaceAll(',','.'));if(cat==null||n==null||n<=0){msg(c,'Isi kategori dan jumlah dengan benar');return;}final d={'id_siswa':student,'id_kategori':cat,'tanggal':date,'keterangan':note.text,'jumlah':n};if(widget.row==null)await DB.i.add('transaksi',d);else await DB.i.edit('transaksi','id_transaksi',widget.row!['id_transaksi'],d);if(c.mounted)Navigator.pop(c,true);}),if(widget.row!=null)TextButton(onPressed:()async{if(await confirm(c,'Hapus transaksi?')){await DB.i.del('transaksi','id_transaksi',widget.row!['id_transaksi']);if(c.mounted)Navigator.pop(c,true);}},child:const Text('Hapus transaksi',style:TextStyle(color:red))) ]));});}
